import {createSummary,shareURL,readShared,summaryText,deliverShare} from './share.mjs';
import {DATA_LICENSES} from './data-licenses.mjs';
import {assess,assessRecords,MODEL_VERSION} from './model.mjs';
import {createProviders,validateAddress} from './providers.mjs';
import {sample} from './samples.mjs';
const $=id=>document.getElementById(id);const providers=createProviders();let current=null,generation=0;
const track=(event,properties={})=>window.dispatchEvent(new CustomEvent('sitebuddy:event',{detail:{event,...properties}}));
const element=(tag,text,className)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;};
function status(text,error=false){$('status').textContent=text;$('status').className=error?'error':'';}
function busy(value){$('search-button').disabled=value;$('sample-mixed').disabled=value;$('sample-sparse').disabled=value;for(const b of $('candidates').querySelectorAll('button'))b.disabled=value;$('search-button').textContent=value?'Working…':'Find location →';}
function reset(){current=null;for(const id of ['deeper-analysis','share-result','another','share-disclosure','manual-share','manual-share-label','share-preview'])$(id).hidden=true;$('share-status').textContent='';$('manual-share').value='';$('download').hidden=true;$('score').textContent='—';$('rating').textContent='No assessment yet';$('mode').textContent='Awaiting location';$('assessment-title').textContent='Your location, in context';$('score-summary').textContent='Three simple dimensions. Equal weights. No hidden predictions.';$('location-detail').textContent='';$('dimensions').replaceChildren();$('provenance').replaceChildren();}
function render(snapshot){
 current=snapshot;for(const id of ['deeper-analysis','share-result','another','share-disclosure'])$(id).hidden=false;$('share-status').textContent='';$('manual-share').hidden=true;$('manual-share-label').hidden=true;$('share-preview').hidden=true;const a=snapshot.assessment;const synthetic=snapshot.kind==='synthetic';
 $('assessment-title').textContent=snapshot.label;$('mode').textContent=synthetic?'Synthetic example':'Live public data';$('score').textContent=a.score===null?'—':a.score.toFixed(1);$('rating').textContent=a.score===null?a.rating:`${a.rating} · mapped context`;
 $('score-summary').textContent=a.score===null?`${a.availableDimensions} of 3 dimensions available. No overall score until all three have usable observations.`:'An illustrative score of mapped context. Not a prediction of commercial success.';
 $('location-detail').textContent=synthetic?'Fictional location · synthetic records · no real-world interpretation':`${snapshot.origin.lat.toFixed(5)}, ${snapshot.origin.lon.toFixed(5)} · 600 m straight-line radius · confirm the location is correct`;
 const cards=a.dimensions.map((d,i)=>{const card=element('article',undefined,'panel dimension');card.append(element('span',`0${i+1}`,'number'),element('h3',d.name),element('p',d.score===null?'Unavailable':`${d.score.toFixed(1)} / 10`,'dimension-score'));const meter=element('meter');meter.min=0;meter.max=10;meter.value=d.score??0;meter.setAttribute('aria-label',`${d.name}: ${d.score===null?'unavailable':d.score.toFixed(1)+' out of 10'}`);meter.hidden=d.score===null;card.append(meter,element('p',d.explanation));return card;});$('dimensions').replaceChildren(...cards);
 const lines=[synthetic?'Source: independently generated synthetic data.':`Source: ${snapshot.provider}. Retrieved ${snapshot.fetchedAt}.`,synthetic?`Synthetic fixture date: ${snapshot.sourceTime.slice(0,10)}. Not an observation date.`:`Dataset release date: ${snapshot.sourceTime.slice(0,10)} · release ${snapshot.release}. Monthly data; individual features may be older.`,`Public rubric: ${MODEL_VERSION}. ${snapshot.records.length} normalized mapped records. No demand, revenue, or lease decision.`,`Data license: ${synthetic?'CC0 for synthetic fixtures.':'Overture Places: CDLA-Permissive-2.0, Apache-2.0 and CC0. Base: ODbL. © OpenStreetMap contributors and Overture Maps Foundation. See data credits below.'}`];$('provenance').replaceChildren(...lines.map(t=>element('p',t)));$('download').hidden=false;
}
export function showSample(kind){track('analysis_started',{kind:'synthetic'});generation++;busy(false);$('candidates').replaceChildren();$('address').value='';const s=sample(kind);const result=assess(s.raw,s.origin,{now:Date.parse(s.evaluationTime)});const {records,sourceTime,...assessment}=result;render({schemaVersion:1,kind:'synthetic',label:s.label,origin:s.origin,sourceTime,fetchedAt:s.evaluationTime,modelVersion:MODEL_VERSION,records,assessment,license:'https://creativecommons.org/publicdomain/zero/1.0/'});track(assessment.score===null?'analysis_withheld':'analysis_succeeded',{kind:'synthetic'});status('Synthetic example loaded. These are fictional map records, not observations about a real address.');return {kind:'synthetic',score:assessment.score,availableDimensions:assessment.availableDimensions};}
async function selectLocation(location){if(!$('consent').checked){status('Consent is required before sending coordinates to the public provider.',true);return;}track('address_confirmed',{kind:'public'});const token=++generation;reset();busy(true);status('Retrieving mapped context…');try{const c=await providers.context(location.origin,{onProgress:message=>{if(token===generation)status(message);}});if(token!==generation)return;const assessment=assessRecords(c.records,location.origin);render({schemaVersion:1,kind:'public',dataLicenses:DATA_LICENSES,label:location.label,origin:location.origin,sourceTime:c.sourceTime,fetchedAt:c.fetchedAt,modelVersion:MODEL_VERSION,provider:c.provider,release:c.release,normalizationVersion:'overture-lite-1',records:c.records,assessment,license:c.license});$('candidates').replaceChildren();track(assessment.score===null?'analysis_withheld':'analysis_succeeded',{kind:'public'});status(assessment.score===null?'Some dimensions are unavailable. The overall score has been withheld.':'Assessment ready. Map completeness and individual feature recency remain unknown.');}catch(e){if(token===generation){track('analysis_failed',{kind:'public',failure:'context'});status(e.message,true);}}finally{if(token===generation)busy(false);}}
$('search-form').addEventListener('submit',async e=>{e.preventDefault();if(!$('consent').checked){status('Please confirm public-provider sharing before searching.',true);return;}track('analysis_started',{kind:'public'});const token=++generation;reset();$('candidates').replaceChildren();let query;try{query=validateAddress($('address').value);}catch(error){track('analysis_failed',{kind:'public',failure:'input'});status(error.message,true);return;}track('address_submitted',{kind:'public'});busy(true);status('Finding address-level matches…');try{const matches=await providers.geocode(query);if(token!==generation)return;if(!matches.length){track('analysis_failed',{kind:'public',failure:'geocoding'});status('No address-level match found. Add the street number, city, and country. A city centroid will not be scored.',true);return;}status('Confirm a match before retrieving its context. Results may not match your intended address.');$('candidates').append(element('p','Check the address and coordinates.'));for(const m of matches){const b=element('button',`${m.label} · ${m.origin.lat.toFixed(5)}, ${m.origin.lon.toFixed(5)} →`,'secondary');b.type='button';b.addEventListener('click',()=>selectLocation(m));$('candidates').append(b);}}catch(error){if(token===generation){track('analysis_failed',{kind:'public',failure:'geocoding'});status(error.message,true);}}finally{if(token===generation)busy(false);}});
$('sample-mixed').addEventListener('click',()=>showSample('mixed'));$('sample-sparse').addEventListener('click',()=>showSample('sparse'));
$('download').addEventListener('click',()=>{if(!current)return;const blob=new Blob([JSON.stringify(current,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=element('a');a.href=url;a.download='site-assessment.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
// Optional proposed browser API; the ordinary interface works without it.
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{void Promise.resolve(context.registerTool({name:'show_synthetic_site_assessment',title:'Explore a fictional site',description:'Show a fictional site assessment in the visible interface. No network requests or real location data.',inputSchema:{type:'object',properties:{example:{type:'string',enum:['mixed','sparse']}},required:['example'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length!==1||!['mixed','sparse'].includes(input.example))throw new Error('Choose mixed or sparse.');return showSample(input.example);}},{signal:lifecycle.signal})).catch(()=>{});}catch{/* Unsupported optional API; ordinary controls remain available. */}}

$('another').addEventListener('click',()=>{track('repeat_analysis',{kind:current?.kind??'none'});generation++;reset();$('candidates').replaceChildren();$('address').value='';status('Try another public U.S. address.');$('address').focus();});
$('share-result').addEventListener('click',async()=>{
 if(!current)return;track('share_clicked',{kind:current.kind});const snapshot=current,button=$('share-result');button.disabled=true;
 try{const text=summaryText(createSummary(snapshot)),url=shareURL(snapshot,location.href);const outcome=await deliverShare({text,url,writeText:navigator.clipboard?.writeText.bind(navigator.clipboard)});
 track(outcome==='copied'?'share_copied':'share_manual',{kind:snapshot.kind});if(current!==snapshot)return;
 $('share-status').textContent=outcome==='copied'?'Summary and link copied. Your address was not included.':'Automatic copying is unavailable. Copy the text below.';
 $('manual-share').value=text+'\n'+url;$('manual-share').hidden=false;$('manual-share-label').hidden=false;$('share-preview').href=url;$('share-preview').hidden=false;if(outcome==='manual'){$('manual-share').focus();$('manual-share').select();}
 }catch{$('share-status').textContent='This result could not be shared. You can still save a replay snapshot.';}finally{button.disabled=false;}
});
try{const shared=readShared(location.hash);if(shared){$('shared-summary').hidden=false;$('shared-detail').textContent=summaryText(shared);$('shared-values').textContent=`${shared.day} · Retail: ${shared.scores[0]??'unknown'} · Amenities: ${shared.scores[1]??'unknown'} · Transit: ${shared.scores[2]===null?'unknown':shared.scores[2].toFixed(1)}`;}}catch{$('shared-summary').hidden=false;$('shared-detail').textContent='This shared summary is invalid. Start your own assessment below.';}

// Enable intake only after the complete core module has initialized.
for(const id of ['address','consent','search-button','sample-mixed','sample-sparse'])$(id).disabled=false;
